void js_EmitTryCatchFinally(J, js_Ast *trystm, js_Ast *catchvar, js_Ast *catchstm, js_Ast *finallystm) {
    int exc_label = js_GetLabel();
    int end_label = js_GetLabel();
    int finally_label = js_GetLabel();

    js_EmitJump(exc_label);
    js_EmitLabel(trystm->label);

    if (js_HasException()) {
        js_EmitJump(catchstm->label);
        js_EmitLabel(exc_label);
        if (js_IsStrictMode()) {
            if (catchvar && catchvar->type == JS_AST_VAR) {
                js_ReportError("Catch variable cannot be declared in strict mode");
            }
        }
        js_EmitAssign(catchvar, js_GetException());
        js_EmitLabel(catchstm->label);
        js_EmitStatements(catchstm);
        if (js_ShouldRethrow()) {
            js_EmitThrow(js_GetException());
        }
    }

    js_EmitJump(finally_label);
    js_EmitLabel(finallystm->label);
    js_EmitStatements(finallystm);
    js_EmitJump(end_label);
    js_EmitLabel(end_label);
}

void emit_try_catch_finally(JS_Ast *trystm, JS_Ast *catchvar, JS_Ast *catchstm, JS_Ast *finallystm) {
    // Begin by emitting a label for the start of the try block
    emit_label(J, "try_start");

    // Emit code for the try block
    emit_statement(J, trystm);

    // Emit a jump to the finally block if no exception is thrown
    emit_jump(J, "finally_start");

    // Emit a label for the start of the catch block
    emit_label(J, "catch_start");

    // Check for strict mode violations on the catch variable
    if (is_strict_mode(J)) {
        if (is_invalid_catch_variable(J, catchvar)) {
            report_error(J, "Catch variable is not allowed in strict mode.");
        }
    }

    // Assign the exception to the catch variable
    emit_assignment(J, catchvar, "exception");

    // Emit code for the catch block
    emit_statement(J, catchstm);

    // Rethrow the exception if necessary
    if (should_rethrow(J)) {
        emit_rethrow(J);
    }

    // Emit a jump to the finally block
    emit_jump(J, "finally_start");

    // Emit a label for the start of the finally block
    emit_label(J, "finally_start");

    // Emit code for the finally block
    emit_statement(J, finallystm);
}

void js_EmitTryCatchFinally(J *J, js_Ast *trystm, js_Ast *catchvar, js_Ast *catchstm, js_Ast *finallystm) {
    int exception_label = J->label_count++;
    int finally_label = J->label_count++;
    int end_label = J->label_count++;

    js_EmitJump(J, exception_label);

    // Emit the try block
    js_EmitBlock(J, trystm);

    // Jump to the finally block if no exception is thrown
    js_EmitJump(J, finally_label);

    // Exception handling label
    js_EmitLabel(J, exception_label);

    // Handle strict mode violation on the catch variable if needed
    if (catchvar && J->strict_mode) {
        // Assume js_CheckStrictViolation is a helper function in the codebase
        js_CheckStrictViolation(J, catchvar);
    }

    // Emit the catch block
    if (catchstm) {
        js_EmitBlock(J, catchstm);
    }

    // Rethrow the exception if needed
    if (J->exception_caught) {
        js_EmitRethrow(J);
    }

    // Jump to the finally block
    js_EmitJump(J, finally_label);

    // Finally label
    js_EmitLabel(J, finally_label);

    // Emit the finally block
    if (finallystm) {
        js_EmitBlock(J, finallystm);
    }

    // Jump to the end
    js_EmitJump(J, end_label);

    // End label
    js_EmitLabel(J, end_label);
}

void js_emit_try_finally(J *J, js_Ast *trystm, js_Ast *catchvar, js_Ast *catchstm, js_Ast *finallystm) {
    int catch_label = J->label++;
    int end_label = J->label++;
    int continue_label = J->label++;
    int exception_label = J->label++;

    js_emit_label(J, catch_label);
    js_emit_op(J, OP_TRY);
    js_emit_ast(J, trystm);

    js_emit_jump(J, end_label);

    js_emit_label(J, exception_label);
    if (catchvar != NULL) {
        js_emit_set_except_var(J, catchvar);
    }

    js_emit_ast(J, catchstm);

    if (catchvar != NULL) {
        js_emit_unset_except_var(J);
    }

    js_emit_jump(J, continue_label);

    js_emit_label(J, end_label);
    js_emit_ast(J, finallystm);
    js_emit_jump(J, continue_label);

    js_emit_label(J, continue_label);
}

void js_EmitTryCatchFinally(JSTranslator *J, js_Ast *trystm, js_Ast *catchvar, js_Ast *catchstm, js_Ast *finallystm) {
    int exceptionLabel = J->currentExceptionLabel++;

    // Emit code to jump to the try block
    EmitLabel(J, exceptionLabel);

    // Emit the try block
    EmitStatement(J, trystm);

    // Emit label for the end of try/catch
    int endLabel = J->currentLabel++;
    EmitJump(J, endLabel);

    // Emit the catch block
    EmitLabel(J, J->currentExceptionLabel++);

    // Check for strict mode violations on the catch variable
    if (J->strictMode) {
        EmitStrictModeViolationCheck(J, catchvar);
    }

    // Emit the catch statement
    EmitStatement(J, catchstm);

    // Rethrow the exception if necessary
    EmitRethrowException(J);

    // Jump to the finally block
    EmitJump(J, endLabel);

    // Emit the finally block
    EmitLabel(J, J->currentLabel++);
    EmitStatement(J, finallystm);

    // Emit the end label
    EmitLabel(J, endLabel);
}
